import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not parameters:
        raise Exception("URL and parameters must be provided.")
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"Failed to retrieve data: {e}")
    if not data:
        raise Exception("Empty data received.")
    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Invalid data format: {e}")
    if df.empty:
        raise Exception("DataFrame is empty after conversion.")
    numeric_df = df.select_dtypes(include=['number'])
    if numeric_df.empty:
        raise Exception("No numerical columns found for correlation.")
    corr = numeric_df.corr()
    ax = sns.heatmap(corr, annot=True, cmap='coolwarm')
    return (df, ax)

import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    if not username or not isinstance(username, str):
        raise ValueError("Username must be a non-empty string.")
    response = requests.get(URL + username)
    response.raise_for_status()
    data = response.json()
    normalized = {}
    for key, value in data.items():
        if isinstance(value, str):
            normalized[key] = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
        else:
            normalized[key] = value
    return normalized

from flask import Flask
from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)
    class DataFetcher(Resource):
